const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Bobiri Forest Reserve geometry (approximate polygon in Ghana)
  const bobiriGeometry = ee.Geometry.Polygon([
    [[-2.28, 6.65], [-2.28, 6.50], [-2.12, 6.50], [-2.12, 6.65], [-2.28, 6.65]]
  ]);

  // 2. Load Hansen Global Forest Change dataset
  const gfc = ee.Image('UMD/hansen/global_forest_change_2023_v1_10');

  // Extract tree cover in 2003 (first_b50 = 2003 baseline)
  const treeCover2003 = gfc.select('treecover2000'); // baseline year 2000

  // Calculate forest loss by 2023
  const forestLoss = gfc.select('loss'); // binary: 1 = loss, 0 = no loss
  const lossYear = gfc.select('lossyear'); // year of loss (2001-2023)

  // 3. Calculate tree cover in 2003 (using 2000 baseline)
  const stats2003 = treeCover2003
    .reduceRegion(
      ee.Reducer.mean(),
      bobiriGeometry,
      30,
      { maxPixels: 1e9 }
    )
    .getInfo();

  const meanTreeCover2003 = stats2003['treecover2000'];

  // 4. Calculate forest loss pixels (loss year 4-23 = years 2004-2023)
  const lossPixels = forestLoss
    .reduceRegion(
      ee.Reducer.sum(),
      bobiriGeometry,
      30,
      { maxPixels: 1e9 }
    )
    .getInfo();

  const totalLossPixels = lossPixels['loss'];

  // 5. Calculate total forest pixels in 2003
  const forestPixels2003 = treeCover2003.gt(50) // pixels with >50% tree cover
    .reduceRegion(
      ee.Reducer.sum(),
      bobiriGeometry,
      30,
      { maxPixels: 1e9 }
    )
    .getInfo();

  const totalForestPixels = forestPixels2003['treecover2000'];

  // 6. Calculate forest cover change
  print(`Tree Cover 2000 (baseline): ${meanTreeCover2003 !== null ? meanTreeCover2003.toFixed(2) : 'N/A'}%`);
  print(`Forest Loss Pixels (2001-2023): ${totalLossPixels !== null ? totalLossPixels : 0}`);
  print(`Forest Pixels >50% Cover 2000: ${totalForestPixels !== null ? totalForestPixels : 0}`);

  // 7. Validate data
  if (meanTreeCover2003 === null || meanTreeCover2003 === undefined) {
    print('Data Validation: Failed - No valid tree cover data found');
    print('<answer>C1</answer>');
    return;
  }

  if (totalLossPixels === null || totalLossPixels === undefined || totalLossPixels === 0) {
    print('Data Validation: No loss pixels detected or invalid');
    // Still could be valid (no loss = no decline)
    totalLossPixels = 0;
  }

  if (totalForestPixels === null || totalForestPixels === undefined || totalForestPixels === 0) {
    print('Data Validation: No forest pixels found');
    print('<answer>C2</answer>');
    return;
  }

  // 8. Determine answer
  const lossPercentage = (totalLossPixels / totalForestPixels) * 100;
  print(`Forest Loss Percentage: ${lossPercentage.toFixed(2)}%`);

  if (totalLossPixels > 0) {
    print('Conclusion: Forest cover DECLINED between 2003 and 2023');
    print('<answer>A</answer>');
  } else {
    print('Conclusion: No significant forest loss detected');
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
